/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field ItemType.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(SalesTable, METSalesOrderType))]
internal class METGUPPricingAttributeSalesTableISalesOrderType extends METGUPPricingAttributeSalesTable implements GUPIPricingAttribute
{
}

Method.Source:
/// <summary>
/// Get value of the attribute
/// </summary>
/// <param name = "_pricingObject">Common</param>
/// <returns>anytype</returns>
public anytype getValueOfAttribute(Common _pricingObject)
{
    return this.getTableRecord(_pricingObject).METSalesOrderType;
}

/// <summary>
/// Retuns the name of the attribute
/// </summary>
/// <returns>name of attribute</returns>
public str getName()
{
    return fieldPName(SalesTable, METSalesOrderType);
}

/// <summary>
/// Get attribte data type
/// </summary>
/// <returns>AttributeDataType</returns>
public AttributeDataType getDataType()
{
    return AttributeDataType::Text;
}

/// <summary>
/// Provide correct table path.
/// </summary>
/// <returns>The table field path if table field exists; otherwise 'PATH_NOT_EXIST'.</returns>
public GUPPricingAttributeTableFieldPath getPath()
{
    return METConstants::pathNotExist;
}

public FieldId getField()
{
    return fieldNum(SalesTable, METSalesOrderType);
}

